CREATE TABLE customer_profiles (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, cpf TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '');
CREATE TABLE addresses (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, recipient TEXT NOT NULL, cep TEXT NOT NULL, street TEXT NOT NULL, number TEXT NOT NULL, complement TEXT NOT NULL DEFAULT '', district TEXT NOT NULL, city TEXT NOT NULL, state TEXT NOT NULL);
ALTER TABLE orders ADD COLUMN delivery_json TEXT;
